// レアリティ別確率
const RARITY_RATES: Record<Rarity, number> = {
  ICON: 0.005,
  HERO: 0.015,
  UR: 0.03,
  SR: 0.12,
  R: 0.28,
  N: 0.55,
};

// パック1枚分のカードを抽選する
export function drawSingleCard(): Player {
  const rand = Math.random();
  let rarity: Rarity;
  if (rand < RARITY_RATES.ICON) rarity = "ICON";
  else if (rand < RARITY_RATES.ICON + RARITY_RATES.HERO) rarity = "HERO";
  else if (rand < RARITY_RATES.ICON + RARITY_RATES.HERO + RARITY_RATES.UR) rarity = "UR";
  else if (rand < RARITY_RATES.ICON + RARITY_RATES.HERO + RARITY_RATES.UR + RARITY_RATES.SR) rarity = "SR";
  else if (rand < RARITY_RATES.ICON + RARITY_RATES.HERO + RARITY_RATES.UR + RARITY_RATES.SR + RARITY_RATES.R) rarity = "R";
  else rarity = "N";

  const pool = ALL_PLAYERS.filter(p => p.rarity === rarity);
  return pool[Math.floor(Math.random() * pool.length)];
}

// パック5枚を抽選（最低1枚はR以上を保証）
export function drawPack(): Player[] {
  const cards: Player[] = [];
  // 最初の1枚はR以上保証
  const rand = Math.random();
  let guaranteedRarity: Rarity;
  if (rand < 0.01) guaranteedRarity = "ICON";
  else if (rand < 0.03) guaranteedRarity = "HERO";
  else if (rand < 0.08) guaranteedRarity = "UR";
  else if (rand < 0.25) guaranteedRarity = "SR";
  else guaranteedRarity = "R";
  const guaranteedPool = ALL_PLAYERS.filter(p => p.rarity === guaranteedRarity);
  cards.push(guaranteedPool[Math.floor(Math.random() * guaranteedPool.length)]);
  // 残り4枚は通常抽選
  for (let i = 0; i < 4; i++) {
    cards.push(drawSingleCard());
  }
  return cards.sort(() => Math.random() - 0.5);
}
