// ノーマルパック（1枚・N/R中心）
export function drawNormalPack(): Player[] {
  const rates = { N: 0.70, R: 0.28, SR: 0.02, UR: 0, HERO: 0, ICON: 0 };
  const rand = Math.random();
  let rarity: Rarity;
  if (rand < rates.ICON) rarity = 'ICON';
  else if (rand < rates.ICON + rates.HERO) rarity = 'HERO';
  else if (rand < rates.ICON + rates.HERO + rates.UR) rarity = 'UR';
  else if (rand < rates.ICON + rates.HERO + rates.UR + rates.SR) rarity = 'SR';
  else if (rand < rates.ICON + rates.HERO + rates.UR + rates.SR + rates.R) rarity = 'R';
  else rarity = 'N';
  const pool = ALL_PLAYERS.filter(p => p.rarity === rarity);
  return [pool[Math.floor(Math.random() * pool.length)]];
}

// 10連ガチャ（SR以上1枚確定）
export function drawTenPack(): Player[] {
  const rates = { ICON: 0.005, HERO: 0.01, UR: 0.05, SR: 0.18, R: 0.25, N: 0.505 };
  const drawOne = (): Player => {
    const rand = Math.random();
    let rarity: Rarity;
    if (rand < rates.ICON) rarity = 'ICON';
    else if (rand < rates.ICON + rates.HERO) rarity = 'HERO';
    else if (rand < rates.ICON + rates.HERO + rates.UR) rarity = 'UR';
    else if (rand < rates.ICON + rates.HERO + rates.UR + rates.SR) rarity = 'SR';
    else if (rand < rates.ICON + rates.HERO + rates.UR + rates.SR + rates.R) rarity = 'R';
    else rarity = 'N';
    const pool = ALL_PLAYERS.filter(p => p.rarity === rarity);
    return pool[Math.floor(Math.random() * pool.length)];
  };
  const cards: Player[] = [];
  // 9枚は通常抽選
  for (let i = 0; i < 9; i++) cards.push(drawOne());
  // 1枚はSR以上確定
  const guaranteedRates = { ICON: 0.01, HERO: 0.03, UR: 0.15, SR: 0.71 };
  const gr = Math.random();
  let gRarity: Rarity;
  if (gr < guaranteedRates.ICON) gRarity = 'ICON';
  else if (gr < guaranteedRates.ICON + guaranteedRates.HERO) gRarity = 'HERO';
  else if (gr < guaranteedRates.ICON + guaranteedRates.HERO + guaranteedRates.UR) gRarity = 'UR';
  else gRarity = 'SR';
  const gPool = ALL_PLAYERS.filter(p => p.rarity === gRarity);
  cards.push(gPool[Math.floor(Math.random() * gPool.length)]);
  return cards.sort(() => Math.random() - 0.5);
}

// レジェンドパック（SR以上確定・ICON/HERO高確率）
export function drawLegendPack(): Player[] {
  const cards: Player[] = [];
  const drawOne = (): Player => {
    const rand = Math.random();
    let rarity: Rarity;
    if (rand < 0.10) rarity = 'ICON';
    else if (rand < 0.30) rarity = 'HERO';
    else if (rand < 0.60) rarity = 'UR';
    else rarity = 'SR';
    const pool = ALL_PLAYERS.filter(p => p.rarity === rarity);
    return pool[Math.floor(Math.random() * pool.length)];
  };
  for (let i = 0; i < 5; i++) cards.push(drawOne());
  return cards.sort(() => Math.random() - 0.5);
}

// Jリーグパック（日本人・Jリーグ選手のみ）
export function drawJLeaguePack(): Player[] {
  const jPool = ALL_PLAYERS.filter(p =>
    p.league === 'Jリーグ' || p.country === 'Japan'
  );
  const rates = { ICON: 0, HERO: 0, UR: 0.03, SR: 0.12, R: 0.35, N: 0.50 };
  const drawOne = (): Player => {
    const rand = Math.random();
    let rarity: Rarity;
    if (rand < rates.UR) rarity = 'UR';
    else if (rand < rates.UR + rates.SR) rarity = 'SR';
    else if (rand < rates.UR + rates.SR + rates.R) rarity = 'R';
    else rarity = 'N';
    const pool = jPool.filter(p => p.rarity === rarity);
    if (pool.length === 0) {
      const fallback = jPool.filter(p => p.rarity === 'N');
      return fallback[Math.floor(Math.random() * fallback.length)];
    }
    return pool[Math.floor(Math.random() * pool.length)];
  };
  const cards: Player[] = [];
  // 1枚はR以上保証
  const gRand = Math.random();
  let gRarity: Rarity;
  if (gRand < 0.03) gRarity = 'UR';
  else if (gRand < 0.15) gRarity = 'SR';
  else gRarity = 'R';
  const gPool = jPool.filter(p => p.rarity === gRarity);
  if (gPool.length > 0) cards.push(gPool[Math.floor(Math.random() * gPool.length)]);
  else cards.push(drawOne());
  for (let i = 0; i < 4; i++) cards.push(drawOne());
  return cards.sort(() => Math.random() - 0.5);
}

// パック種別に応じてドローする統合関数
export function drawByPackType(packType: PackType): Player[] {
  switch (packType) {
    case 'normal': return drawNormalPack();
    case 'standard': return drawPack();
    case 'ten': return drawTenPack();
    case 'legend': return drawLegendPack();
    case 'jleague': return drawJLeaguePack();
    default: return drawPack();
  }
}

